import io
import unittest
from fastapi import FastAPI, HTTPException
from fastapi.testclient import TestClient
from pydantic import BaseModel

def create_app():
    app = FastAPI()
    data = {}
    class Input(BaseModel):
        judul: str
    @app.post("/tiket", status_code=201)
    def buat(body: Input):
        nomor = len(data) + 1
        data[nomor] = {"id": nomor, "judul": body.judul}
        return data[nomor]
    @app.get("/tiket/{nomor}")
    def ambil(nomor: int):
        if nomor not in data:
            raise HTTPException(404, "Tiket tidak ditemukan")
        return data[nomor]
    return app

class TesAPI(unittest.TestCase):
    def test_buat_dan_baca(self):
        with TestClient(create_app()) as client:
            hasil = client.post("/tiket", json={"judul": "Link"})
            self.assertEqual(hasil.status_code, 201)
            self.assertEqual(client.get("/tiket/1").json()["judul"], "Link")
    def test_isolasi_dan_invalid(self):
        with TestClient(create_app()) as client:
            self.assertEqual(client.get("/tiket/1").status_code, 404)
            self.assertEqual(client.post("/tiket", json={}).status_code, 422)

suite = unittest.defaultTestLoader.loadTestsFromTestCase(TesAPI)
