import os
from contextlib import asynccontextmanager
from typing import Annotated, Literal
from fastapi import FastAPI, Depends, HTTPException, Query
from pydantic import BaseModel, ConfigDict, Field, StrictInt, StringConstraints
from sqlalchemy import create_engine, event, Integer, String, ForeignKey, CheckConstraint, select, update, func
from sqlalchemy.orm import DeclarativeBase, Mapped, mapped_column, Session

class Base(DeclarativeBase):
    pass

class Teknisi(Base):
    __tablename__ = "teknisi_api"
    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    kode: Mapped[str] = mapped_column(String(30), unique=True)
    nama: Mapped[str] = mapped_column(String(80))

class Tiket(Base):
    __tablename__ = "tiket_api"
    __table_args__ = (
        CheckConstraint("status IN ('BARU','DIPROSES','SELESAI')"),
        CheckConstraint("length(trim(judul)) > 0"),
        CheckConstraint("status = 'BARU' OR teknisi_id IS NOT NULL"),
    )
    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    judul: Mapped[str] = mapped_column(String(120))
    status: Mapped[str] = mapped_column(String(20), default="BARU")
    teknisi_id: Mapped[int | None] = mapped_column(ForeignKey("teknisi_api.id"))

class Riwayat(Base):
    __tablename__ = "riwayat_api"
    id: Mapped[int] = mapped_column(Integer, primary_key=True)
    tiket_id: Mapped[int] = mapped_column(ForeignKey("tiket_api.id"))
    status: Mapped[str] = mapped_column(String(20))

Teks = Annotated[str, StringConstraints(strip_whitespace=True, min_length=1, max_length=120)]

class TiketInput(BaseModel):
    model_config = ConfigDict(extra="forbid")
    judul: Teks

class TeknisiInput(BaseModel):
    model_config = ConfigDict(extra="forbid")
    kode: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1, max_length=30)]
    nama: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1, max_length=80)]

class StatusInput(BaseModel):
    model_config = ConfigDict(extra="forbid")
    status: Literal["DIPROSES", "SELESAI"]
    teknisi_id: StrictInt | None = Field(default=None, gt=0)

class TiketOutput(BaseModel):
    id: int
    judul: str
    status: str
    teknisi_id: int | None

def tampilan(tiket):
    return {"id": tiket.id, "judul": tiket.judul, "status": tiket.status, "teknisi_id": tiket.teknisi_id}

def create_app(database_url):
    options = {"check_same_thread": False} if database_url.startswith("sqlite") else {}
    engine = create_engine(database_url, connect_args=options, pool_pre_ping=True)
    if engine.dialect.name == "sqlite":
        @event.listens_for(engine, "connect")
        def aktifkan_fk(connection, _):
            cursor = connection.cursor()
            cursor.execute("PRAGMA foreign_keys = ON")
            cursor.close()
    # Hanya bootstrap database latihan baru, bukan pengganti migrasi.
    Base.metadata.create_all(engine)
    @asynccontextmanager
    async def lifespan(app):
        yield
        engine.dispose()
    app = FastAPI(lifespan=lifespan)
    app.state.engine = engine

    def db():
        with Session(engine) as session:
            yield session

    @app.post("/teknisi", status_code=201)
    def buat_teknisi(body: TeknisiInput, session: Session = Depends(db)):
        from sqlalchemy.exc import IntegrityError
        try:
            with session.begin():
                orang = Teknisi(**body.model_dump())
                session.add(orang)
                session.flush()
                hasil = {"id": orang.id, "kode": orang.kode, "nama": orang.nama}
            return hasil
        except IntegrityError as error:
            raise HTTPException(409, "Kode teknisi bentrok") from error

    @app.post("/tiket", status_code=201, response_model=TiketOutput)
    def buat_tiket(body: TiketInput, session: Session = Depends(db)):
        with session.begin():
            tiket = Tiket(judul=body.judul, status="BARU")
            session.add(tiket)
            session.flush()
            session.add(Riwayat(tiket_id=tiket.id, status="BARU"))
            hasil = tampilan(tiket)
        return hasil

    @app.get("/tiket", response_model=list[TiketOutput])
    def daftar(setelah: int = Query(0, ge=0), limit: int = Query(20, ge=1, le=100), session: Session = Depends(db)):
        return [tampilan(t) for t in session.scalars(select(Tiket).where(Tiket.id > setelah).order_by(Tiket.id).limit(limit))]

    @app.get("/tiket/{nomor}", response_model=TiketOutput)
    def ambil(nomor: int, session: Session = Depends(db)):
        tiket = session.get(Tiket, nomor)
        if tiket is None:
            raise HTTPException(404, "Tiket tidak ditemukan")
        return tampilan(tiket)

    @app.patch("/tiket/{nomor}/status", response_model=TiketOutput)
    def ubah(nomor: int, body: StatusInput, session: Session = Depends(db)):
        with session.begin():
            tiket = session.get(Tiket, nomor, with_for_update=True)
            if tiket is None:
                raise HTTPException(404, "Tiket tidak ditemukan")
            petugas = tiket.teknisi_id
            if tiket.status == "BARU" and body.status == "DIPROSES" and body.teknisi_id is not None:
                if session.get(Teknisi, body.teknisi_id) is None:
                    raise HTTPException(404, "Teknisi tidak ditemukan")
                petugas = body.teknisi_id
            elif tiket.status == "DIPROSES" and body.status == "SELESAI" and body.teknisi_id is None:
                pass
            else:
                raise HTTPException(409, "Transisi tidak diizinkan")
            lama = tiket.status
            hasil_update = session.execute(update(Tiket).where(Tiket.id == nomor, Tiket.status == lama)
                                           .values(status=body.status, teknisi_id=petugas))
            if hasil_update.rowcount != 1:
                raise HTTPException(409, "Status sudah berubah")
            session.add(Riwayat(tiket_id=nomor, status=body.status))
            hasil = {"id": nomor, "judul": tiket.judul, "status": body.status, "teknisi_id": petugas}
        return hasil

    @app.get("/tiket/{nomor}/riwayat")
    def riwayat(nomor: int, session: Session = Depends(db)):
        if session.get(Tiket, nomor) is None:
            raise HTTPException(404, "Tiket tidak ditemukan")
        return [{"id": r.id, "status": r.status} for r in session.scalars(
            select(Riwayat).where(Riwayat.tiket_id == nomor).order_by(Riwayat.id))]

    @app.get("/laporan")
    def laporan(session: Session = Depends(db)):
        hasil = {"BARU": 0, "DIPROSES": 0, "SELESAI": 0}
        hasil.update(dict(session.execute(select(Tiket.status, func.count()).group_by(Tiket.status)).all()))
        return hasil
    return app

def create_from_env():
    url = os.environ.get("DATABASE_URL")
    if not url:
        raise RuntimeError("DATABASE_URL wajib diatur untuk database latihan")
    return create_app(url)

