from typing import Annotated
from fastapi import FastAPI, HTTPException, Query, Response
from fastapi.testclient import TestClient
from pydantic import BaseModel, ConfigDict, StringConstraints

class JudulInput(BaseModel):
    model_config = ConfigDict(extra="forbid")
    judul: Annotated[str, StringConstraints(strip_whitespace=True, min_length=1, max_length=120)]

def create_app():
    app, data = FastAPI(), {}
    nomor_berikut = 1
    @app.post("/tiket", status_code=201)
    def buat(body: JudulInput):
        nonlocal nomor_berikut
        nomor = nomor_berikut
        nomor_berikut += 1
        data[nomor] = {"id": nomor, "judul": body.judul}
        return dict(data[nomor])
    @app.get("/tiket")
    def daftar(setelah: int = Query(0, ge=0), limit: int = Query(20, ge=1, le=100)):
        return [dict(data[k]) for k in sorted(data) if k > setelah][:limit]
    @app.get("/tiket/{nomor}")
    def ambil(nomor: int):
        if nomor not in data:
            raise HTTPException(404, "Tiket tidak ditemukan")
        return dict(data[nomor])
    @app.patch("/tiket/{nomor}")
    def ubah(nomor: int, body: JudulInput):
        ambil(nomor)
        data[nomor]["judul"] = body.judul
        return dict(data[nomor])
    @app.delete("/tiket/{nomor}", status_code=204)
    def hapus(nomor: int):
        ambil(nomor)
        del data[nomor]
        return Response(status_code=204)
    return app

if __name__ == "__main__":
