from fastapi import FastAPI, Depends, HTTPException
from fastapi.security import HTTPBearer
from fastapi.testclient import TestClient

def create_app(registry):
    app = FastAPI()
    bearer = HTTPBearer(auto_error=False)
    def current(credentials=Depends(bearer)):
        user = None if credentials is None else registry.get(sha256(credentials.credentials.encode()).hexdigest())
        if user is None:
            raise HTTPException(401, "Token tidak diterima", headers={"WWW-Authenticate": "Bearer"})
        return user
    @app.get("/tiket/{id}")
    def detail(id: int, user=Depends(current)):
        tiket = {"id": 1, "owner_id": 10, "judul": "Link A"}
        if id != 1 or (user["role"] != "supervisor" and user["id"] != tiket["owner_id"]):
            raise HTTPException(404, "Tiket tidak ditemukan")
        return tiket
    @app.get("/supervisor")
    def supervisor(user=Depends(current)):
        if user["role"] != "supervisor":
            raise HTTPException(403, "Perlu supervisor")
        return {"ok": True}
    return app

if __name__ == "__main__":
    token = token_urlsafe(32)
